function Kpi({label,value,sub}:{label:string;value:any;sub:string}){return <div className="kpi card"><span>{label}</span><strong>{value}</strong><small>{sub}</small></div>}
function Card({children,className='' }:{children:any;className?:string}){return <div className={`card ${className}`}>{children}</div>}
function Badge({children,tone='neutral'}:{children:any;tone?:string}){return <span className={`badge ${tone}`}>{children}</span>}
function Money({n}:{n:number}){return <>₹{Math.round(n).toLocaleString('en-IN')}</>}
function Sparkline({values}:{values:number[]}){const min=Math.min(...values),max=Math.max(...values);const pts=values.map((v,i)=>`${i/(values.length-1)*100},${100-(v-min)/(max-min||1)*84}`).join(' ');return <svg viewBox="0 0 100 100" className="spark"><polyline points={pts} fill="none" stroke="currentColor" strokeWidth="2.5" vectorEffect="non-scaling-stroke"/></svg>}
function MiniChart({forecast=false}:{forecast?:boolean}){const vals=forecast?[2812,2830,2848,2863,2880,2897,2916]:history;const min=Math.min(...vals),max=Math.max(...vals);const points=vals.map((v,i)=>`${(i/(vals.length-1))*100},${90-((v-min)/(max-min||1))*70}`).join(' ');return <div className="chart-wrap"><svg viewBox="0 0 100 100" preserveAspectRatio="none" className="chart"><polyline points={points} fill="none" stroke="currentColor" strokeWidth="2.2" vectorEffect="non-scaling-stroke"/></svg><div className="chart-foot"><span>{forecast?'Estimated price range':'7-day market history'}</span><Badge tone="green">₹2,812/qtl</Badge></div></div>}

