function BuyerOffers(){return <><div className="page-intro"><div><p className="eyebrow">Offers</p><h2>Negotiation queue</h2></div></div><Card><div className="payment-row"><div><strong>Ramesh Kumar · LOT-001</strong><span>Soybean · 20 qtl · Sehore</span></div><div><strong>₹3,050/qtl</strong><span>Total ₹61,000</span></div><Badge tone="amber">Pending</Badge><button className="button" onClick={()=>alert('Sample flow: offer accepted and deal created.')}>Accept</button></div></Card></>}
function Orders(){return <><div className="page-intro"><div><p className="eyebrow">Orders</p><h2>Live delivery tracking</h2></div></div><Card><div className="deal-head"><div><Badge tone="blue">IN TRANSIT</Badge><h3>DEMO-DEAL-001</h3><p>Soybean · 20 qtl · Sehore → Nagpur</p></div><Truck size={28}/></div><div className="timeline">{['Pickup','In Transit','Arrival','Delivered'].map((s,i)=><div className={i<2?'done':''} key={s}><div className="circle">{i+1}</div><span>{s}</span></div>)}</div></Card></>}


function Bidding({role}:{role:Role}){const [accepted,setAccepted]=useState<string|null>(null);const [bid,setBid]=useState('3050');const [submitted,setSubmitted]=useState(false);const buyerBids=[['AgroMart Foods','₹3,120','20 qtl','Premium'],['Shakti Foods Pvt Ltd','₹3,050','20 qtl','A'],['Vidarbha Traders','₹2,980','25 qtl','FAQ']];const otherBuyerBids=[['AgroMart Foods','₹3,120','20 qtl','Premium'],['Vidarbha Traders','₹2,980','25 qtl','FAQ']];return <><div className="page-intro"><div><p className="eyebrow">Live demo bidding</p><h2>{role==='farmer'?'Competitive bids for your crop lot':'Bid after seeing the other visible offers'}</h2><p>{role==='farmer'?'Compare verified buyer offers before accepting a deal.':'Review the farmer lot and the other visible buyer bids, then place your own offer.'}</p></div><Badge tone="green">3 verified participants</Badge></div>{role==='farmer'?<Card><div className="section-head"><div><span className="eyebrow">LOT-001 · Ramesh Kumar</span><h3>Soybean · 20 qtl · Sehore</h3></div><Badge tone="blue">A quality · 11.5% moisture</Badge></div><div className="bid-grid">{buyerBids.map(([name,price,qty,quality])=><div className={`bid-card ${accepted===name?'selected':''}`} key={name}><div className="profile-mini"><div className="avatar">{name[0]}</div><div><strong>{name}</strong><span>{qty} · {quality} · Verified buyer</span></div></div><strong className="bid-price">{price}<small>/qtl</small></strong><div className="bid-actions"><button className="button" onClick={()=>setAccepted(name)}>{accepted===name?'Accepted ✓':'Accept bid'}</button><button className="table-action" onClick={()=>window.alert(`${name}: ${price}/qtl for ${qty}.`)}>View</button></div></div>)}</div>{accepted&&<div className="alert green"><strong>Bid accepted: {accepted}</strong><span>Demo deal created from the selected offer. Transport and payment can continue from the Deals section.</span></div>}</Card>:<><Card><div className="section-head"><div><span className="eyebrow">LOT-001 · Ramesh Kumar</span><h3>Soybean · 20 qtl · Sehore</h3></div><Badge tone="blue">A quality · 11.5% moisture</Badge></div><div className="other-bids"><span className="eyebrow">Other visible bids</span>{otherBuyerBids.map(([name,price,qty,quality])=><div className="other-bid-row" key={name}><div><strong>{name}</strong><span>{qty} · {quality} · Verified</span></div><strong>{price}<small>/qtl</small></strong></div>)}</div></Card><Card><div className="section-head"><div><span className="eyebrow">Your offer</span><h3>Place your bid</h3></div><Badge tone="purple">Buyer view</Badge></div><div className="form-grid"><label>Your bid / qtl<input value={bid} onChange={e=>setBid(e.target.value.replace(/[^0-9]/g,''))} inputMode="numeric" /></label><label>Quantity (qtl)<input defaultValue="20" inputMode="numeric"/></label><label>Offer valid until<input type="date" defaultValue="2026-09-26"/></label></div><div className="bid-context"><span>Current visible range</span><strong>₹2,980 – ₹3,120/qtl</strong></div><button className="button" onClick={()=>setSubmitted(true)}>Place bid</button>{submitted&&<div className="alert green"><strong>Bid placed ✓</strong><span>Your demo offer of ₹{Number(bid||0).toLocaleString('en-IN')}/qtl is now visible to the farmer.</span></div>}</Card></>}</>}
function FPO(){const [connected,setConnected]=useState<string|null>(null);const fpos=[['Sehore Farmers Producer Co.','Sehore, MP','Soybean · Wheat','1,240 members','18 km'],['Bhopal Agri FPO Network','Bhopal, MP','Soybean · Pulses','860 members','58 km'],['Vidarbha Grain FPO','Nagpur, MH','Soybean · Cotton','1,540 members','310 km']];return <><div className="page-intro"><div><p className="eyebrow">Collective market access</p><h2>Connect with nearby FPOs</h2><p>Aggregate small lots, improve bargaining power and coordinate transport.</p></div></div><div className="fpo-grid">{fpos.map(([name,loc,crops,members,distance])=><Card className="pressable-card" key={name}><div className="section-head"><div className="profile-mini"><div className="avatar">F</div><div><strong>{name}</strong><span>{loc} · {distance}</span></div></div><Badge tone="green">Verified</Badge></div><div className="checks"><span>{crops}</span><span>{members}</span><span>Aggregation available</span></div><button className="button full" onClick={()=>setConnected(name)}>{connected===name?'Connected ✓':'Request aggregation'}</button></Card>)}</div>{connected&&<div className="alert green"><strong>FPO request sent</strong><span>{connected} has been added to your connections. Demo coordinator response: within 1 working day.</span></div>}</>}

function Polling({role}:{role:Role}){const [choice,setChoice]=useState('');const [voted,setVoted]=useState(false);const farmerOptions=['Sell within 3 days','Wait for a better price','Store for later','Join an FPO / pool'];const buyerOptions=['Verified quality details','Reliable delivery','Competitive price','Faster payment terms'];const options=role==='farmer'?farmerOptions:buyerOptions;const title=role==='farmer'?'What are farmers planning this week?':'What matters most when buyers choose a farmer lot?';const subtitle=role==='farmer'?'A simple farmer pulse helps the demo estimate near-term supply behaviour.':'A buyer pulse shows which sourcing factors are most important in the demo marketplace.';const result=role==='farmer'?[['Sell within 3 days','42%'],['Wait for a better price','29%'],['Store for later','17%'],['Join an FPO / pool','12%']]:[['Verified quality details','34%'],['Reliable delivery','28%'],['Competitive price','25%'],['Faster payment terms','13%']];return <><div className="page-intro"><div><p className="eyebrow">{role==='farmer'?'Farmer pulse':'Buyer pulse'}</p><h2>{title}</h2><p>{subtitle}</p></div><Badge tone="blue">1,248 responses · demo</Badge></div><Card><div className="poll-question-head"><div><span className="eyebrow">One quick question</span><h3>{role==='farmer'?'What would you most likely do with your soybean this week?':'What would make you more comfortable sourcing a farmer lot?'}</h3></div><div className="poll-icon">{role==='farmer'?'🌾':'🤝'}</div></div><div className="poll-options poll-options-4">{options.map((x,i)=><button className={choice===x?'poll-option selected':'poll-option'} key={x} onClick={()=>setChoice(x)}><span>{x}</span><strong>{result[i][1]}</strong></button>)}</div><button className="button" disabled={!choice} onClick={()=>setVoted(true)}>{voted?'Response recorded ✓':'Submit response'}</button>{voted&&<div className="alert green">{role==='farmer'?'Thanks. Your response is added to the demo supply signal.':'Thanks. Your response is added to the demo sourcing-preference signal.'}</div>}</Card><div className="grid-2">{result.slice(0,2).map(([q,p])=><Card key={q}><span className="eyebrow">Current demo signal</span><h4>{q}</h4><strong className="big-number">{p}</strong><p className="muted">of sample responses</p></Card>)}<Card className="poll-summary-card"><span className="eyebrow">Why this matters</span><h4>{role==='farmer'?'Supply planning':'Sourcing planning'}</h4><p>{role==='farmer'?'The pulse helps connect expected selling behaviour with arrivals, storage and transport decisions.':'The pulse helps connect buyer priorities with quality, logistics and marketplace matching.'}</p></Card></div></>}
