export default function App(){return <Routes><Route path="/" element={<Landing/>}/><Route path="/community" element={<CommunityPage/>}/><Route path="/login" element={<LoginPage/>}/><Route path="/farmer/*" element={<Protected role="farmer"/>}/><Route path="/buyer/*" element={<Protected role="buyer"/>}/><Route path="*" element={<Navigate to="/" replace/>}/></Routes>}
function Protected({role}:{role:Role}){const user=useAuthStore(s=>s.user);if(!user)return <Navigate to="/login" replace/>; if(user.role!==role)return <Navigate to={`/${user.role}/dashboard`} replace/>; return <PortalShell role={role}/>}
